import{_ as a,c as n,o as i,a2 as t}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/installation.md","filePath":"de/guide/installation.md","lastUpdated":1793163976000}'),r={name:"de/guide/installation.md"};function l(s,e,o,d,h,p){return i(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>NueZip ist für macOS über den Mac App Store erhältlich.</p><h2 id="download-optionen" tabindex="-1">Download-Optionen <a class="header-anchor" href="#download-optionen" aria-label="Permalink to &quot;Download-Optionen&quot;">​</a></h2><h3 id="mac-app-store-empfohlen" tabindex="-1">Mac App Store (Empfohlen) <a class="header-anchor" href="#mac-app-store-empfohlen" aria-label="Permalink to &quot;Mac App Store (Empfohlen)&quot;">​</a></h3><ul><li><strong>Download</strong>: <a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">NueZip im Mac App Store</a></li></ul><p>Die Mac App Store-Version bietet automatische Updates und nahtlose Integration mit macOS.</p><h3 id="github-releases-alternative" tabindex="-1">GitHub Releases (Alternative) <a class="header-anchor" href="#github-releases-alternative" aria-label="Permalink to &quot;GitHub Releases (Alternative)&quot;">​</a></h3><p>Wenn Sie lieber direkt herunterladen möchten, erhalten Sie die App von <a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a>. Beachten Sie, dass diese Version keine automatischen Updates erhält.</p><h2 id="installationsschritte" tabindex="-1">Installationsschritte <a class="header-anchor" href="#installationsschritte" aria-label="Permalink to &quot;Installationsschritte&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>Klicken Sie auf den Download-Link oben oder suchen Sie im Mac App Store nach „NueZip&quot;</li><li>Klicken Sie auf „Get&quot; (Laden), um die App herunterzuladen</li><li>Die App wird automatisch heruntergeladen und installiert</li><li>Starten Sie NueZip aus Ihrem Programme-Ordner oder dem Launchpad</li></ol><h3 id="github-releases" tabindex="-1">GitHub Releases <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;GitHub Releases&quot;">​</a></h3><ol><li>Laden Sie die neueste <code>.dmg</code> von der Releases-Seite herunter</li><li>Doppelklicken Sie auf die heruntergeladene <code>.dmg</code>, um sie zu öffnen</li><li>Ziehen Sie das <code>NueZip.app</code>-Symbol in Ihren <code>Applications</code>-Ordner</li><li>Werfen Sie das eingehängte Image aus und öffnen Sie <code>NueZip</code> aus <code>Applications</code></li></ol><p>Wenn macOS das Öffnen der App verhindert (Gatekeeper), öffnen Sie <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit</strong> und klicken Sie für NueZip auf <strong>Trotzdem öffnen</strong>, oder klicken Sie mit der rechten Maustaste auf die App und wählen Sie <strong>Öffnen</strong>.</p><h2 id="erster-start" tabindex="-1">Erster Start <a class="header-anchor" href="#erster-start" aria-label="Permalink to &quot;Erster Start&quot;">​</a></h2><p>Wenn Sie NueZip zum ersten Mal starten, werden Sie durch einen Onboarding-Ablauf geführt, um:</p><ul><li><strong>Ordnerzugriff gewähren</strong>: Erlauben Sie NueZip den Zugriff auf gängige Verzeichnisse (Downloads, Dokumente, Desktop)</li><li><strong>Finder-Erweiterung aktivieren</strong>: Aktivieren Sie das Kontextmenü per Rechtsklick für schnelle Archivoperationen</li></ul><p>Gewähren Sie die Berechtigungen, wenn Sie dazu aufgefordert werden. Sie können diese jederzeit in <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit</strong> ändern.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><ul><li><strong>Mac App Store-Version</strong>: Updates werden automatisch vom App Store durchgeführt</li><li><strong>GitHub Releases-Version</strong>: Laden Sie das neuere Release herunter und ersetzen Sie die App in <code>Applications</code></li></ul><h2 id="deinstallation" tabindex="-1">Deinstallation <a class="header-anchor" href="#deinstallation" aria-label="Permalink to &quot;Deinstallation&quot;">​</a></h2><p>So deinstallieren Sie NueZip:</p><ol><li>Beenden Sie NueZip</li><li>Ziehen Sie <code>NueZip.app</code> aus <code>Applications</code> in den Papierkorb</li><li>(Optional) Entfernen Sie App-Daten und -Protokolle:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Logs/nuezip</span></span></code></pre></div><h2 id="systemanforderungen" tabindex="-1">Systemanforderungen <a class="header-anchor" href="#systemanforderungen" aria-label="Permalink to &quot;Systemanforderungen&quot;">​</a></h2><ul><li><strong>macOS</strong>: Sonoma (14) oder neuer empfohlen</li><li><strong>CPU</strong>: Apple Silicon (M-Serie) oder Intel (64-Bit)</li><li><strong>Arbeitsspeicher</strong>: 4 GB mindestens, 8 GB empfohlen</li><li><strong>Speicher</strong>: ~50 MB</li></ul><h2 id="fehlerbehebung" tabindex="-1">Fehlerbehebung <a class="header-anchor" href="#fehlerbehebung" aria-label="Permalink to &quot;Fehlerbehebung&quot;">​</a></h2><p>Wenn bei der Installation Probleme auftreten:</p><ul><li><strong>macOS blockiert die App</strong>: Öffnen Sie <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit</strong> und klicken Sie für NueZip auf <strong>Trotzdem öffnen</strong></li><li><strong>Notarisierungswarnung</strong>: Laden Sie ein signiertes/notarielles Build vom Mac App Store herunter</li></ul><p>Für weitere Hilfe besuchen Sie die <a href="./troubleshooting.html">Fehlerbehebungsanleitung</a>.</p>`,30)])])}const g=a(r,[["render",l]]);export{c as __pageData,g as default};
